BEGIN;

-- 1. Estructura de la tabla objetos
-- Existing rows and dependent objects are never dropped.

CREATE TABLE IF NOT EXISTS objetos (
  id BIGSERIAL PRIMARY KEY,
  url_objeto varchar(512) DEFAULT NULL,
  titulo varchar(512) DEFAULT NULL,
  autor varchar(255) DEFAULT NULL,
  lugar_origen varchar(255) DEFAULT NULL,
  estilo_cultura varchar(255) DEFAULT NULL,
  fecha varchar(255) DEFAULT NULL,
  tipo_objeto varchar(255) DEFAULT NULL,
