  dimensiones varchar(512) DEFAULT NULL,
  creditos varchar(512) DEFAULT NULL,
  otras_denominaciones text,
  imagen_url text,
  imagen_local varchar(255) DEFAULT NULL,
  thumbnail_local varchar(255) DEFAULT NULL,
  estilo_cultura_source text NOT NULL DEFAULT 'legacy',
  lugar_origen_source text NOT NULL DEFAULT 'legacy'
);

-- 2. Índices y restricciones
CREATE INDEX IF NOT EXISTS idx_inventario ON objetos(numero_inventario);
CREATE INDEX IF NOT EXISTS idx_tipo ON objetos(tipo_objeto);
CREATE INDEX IF NOT EXISTS idx_lugar ON objetos(lugar_origen);
CREATE INDEX IF NOT EXISTS idx_cultura ON objetos(estilo_cultura);

