-- 4. Vista para objetos con imagen disponible
CREATE OR REPLACE VIEW objetos_con_imagen AS
SELECT
  id,
  titulo,
  autor,
  lugar_origen,
  estilo_cultura,
  fecha,
  tipo_objeto,
  numero_inventario,
  imagen_url
FROM objetos
WHERE imagen_url IS NOT NULL;

-- 5. Sincronización del autoincremento (secuencia PostgreSQL)
DO $$
DECLARE
  sequence_name TEXT;
  max_id BIGINT;
  sequence_value BIGINT;
BEGIN
  sequence_name := pg_get_serial_sequence('objetos', 'id');
  IF sequence_name IS NOT NULL THEN
    SELECT COALESCE(MAX(id), 0) INTO max_id FROM objetos;
    EXECUTE format('SELECT last_value FROM %s', sequence_name) INTO sequence_value;
    IF sequence_value < max_id THEN
      PERFORM setval(sequence_name, max_id, true);
    END IF;
  END IF;
END
$$;

COMMIT;
